69	/// FNV-1a 64-bit über einen Namen → stabiler Fingerprint (identisch zur f15-Pfad-A-Konvention).
70	[[nodiscard]] inline std::uint64_t fnv1a(std::string_view s) noexcept {
71	    std::uint64_t h = 14695981039346656037ULL;
72	    for (char c : s) {
73	        h ^= static_cast<unsigned char>(c);
74	        h *= 1099511628211ULL;
75	    }
76	    return h;
77	}
78	/// p50 (Median, Nearest-Rank) über die zusammengeführten Op-Latenzen eines Lastprofil-Laufs.
79	[[nodiscard]] inline std::int64_t merged_p50_ns(workload_driver::WorkloadRunResult const& r) {
80	    std::vector<std::int64_t> all;
81	    all.reserve(r.insert_ns.size() + r.lookup_ns.size() + r.erase_ns.size() + r.clear_ns.size());
82	    all.insert(all.end(), r.insert_ns.begin(), r.insert_ns.end());
83	    all.insert(all.end(), r.lookup_ns.begin(), r.lookup_ns.end());
84	    all.insert(all.end(), r.erase_ns.begin(), r.erase_ns.end());
85	    all.insert(all.end(), r.clear_ns.begin(), r.clear_ns.end());
86	    return anatomy_commands::detail::nearest_rank_p(std::move(all), 0.5);
87	}
88	[[nodiscard]] inline double throughput_ops_per_sec(std::uint64_t op_count, std::int64_t total_ns) noexcept {
89	    return (total_ns > 0) ? (static_cast<double>(op_count) / (static_cast<double>(total_ns) / 1'000'000'000.0)) : 0.0;
90	}
91	} // namespace detail
