93	/// Baut den autoritativen POD aus einem host-seitigen Lastprofil-Lauf (V5-I9 WorkloadRunResult).
94	/// Die 16 Performance-Spalten + 6 Observer-Spalten werden mit ECHTEN Mess-/Observer-Werten befüllt;
95	/// die 6 HW-Counter bleiben 0 mit pmc_available=0 (ehrlich, P4-gated).
96	[[nodiscard]] inline ComdareMeasurementSnapshotV1
97	measurement_from_workload_result(workload_driver::WorkloadRunResult const& r, std::string_view permutation_id) {
98	    ComdareMeasurementSnapshotV1 m;
99	    m.fingerprint            = detail::fnv1a(permutation_id);
100	    m.succeeded              = 1;
101	    m.op_count               = r.op_count;
102	    m.total_cycles           = static_cast<std::uint64_t>(detail::merged_p50_ns(r)); // repräsentative ns
103	    m.throughput_ops_per_sec = detail::throughput_ops_per_sec(r.op_count, r.total_ns);
104	    m.pmc_available          = 0; // PMC nicht angebunden
105	    // I1: aus dem konsolidierten Observer-POD (search→axis_stats[0], alloc→axis_stats[6]).
106	    m.bytes_allocated       = r.observer.axis_stats[6][0]; // ECHT aus Observer
107	    m.bytes_in_use_peak     = r.observer.axis_stats[6][1]; // ECHT aus Observer
108	    m.search_insert         = r.observer.axis_stats[0][3];
109	    m.search_lookup         = r.observer.axis_stats[0][0];
110	    m.search_hit            = r.observer.axis_stats[0][1];
111	    m.search_miss           = r.observer.axis_stats[0][2];
112	    m.search_erase          = r.observer.axis_stats[0][4];
113	    m.search_peak_occupancy = r.observer.axis_stats[0][5];
114	    return m;
115	}
